<?php require_once 'config.php';require_admin();$page_title='Kelola Pengguna';$page_desc='Kelola akun Admin dan User.';if(isset($_GET['hapus'])){$s=$pdo->prepare('DELETE FROM users WHERE id=? AND id<>?');$s->execute([(int)$_GET['hapus'],$_SESSION['login']['id']]);flash('success','Pengguna berhasil dihapus.');header('Location: users.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){$s=$pdo->prepare('INSERT INTO users(nama,username,password,role) VALUES(?,?,?,?)');$s->execute([trim($_POST['nama']),trim($_POST['username']),trim($_POST['password']),$_POST['role']]);flash('success','Pengguna berhasil ditambahkan.');header('Location: users.php');exit;}$rows=$pdo->query('SELECT id,nama,username,role,created_at FROM users ORDER BY id DESC')->fetchAll();require 'partials/header.php';?><section class="panel form-panel"><div class="panel-head"><h3>Tambah Pengguna</h3></div><form method="post" class="form-grid"><div><label>Nama</label><input name="nama" required></div><div><label>Username</label><input name="username" required></div><div><label>Password</label><input name="password" required></div><div><label>Role</label><select name="role"><option>Admin</option><option>User</option></select></div><div><button class="btn primary">+ Tambah Akun</button></div></form></section><section class="panel"><div class="panel-head"><h3>Daftar Pengguna</h3></div><div class="table-wrap"><table><thead><tr><th>Nama</th><th>Username</th><th>Role</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $u): ?><tr><td><?=e($u['nama'])?></td><td><?=e($u['username'])?></td><td><span class="badge"><?=e($u['role'])?></span></td><td><?php if($u['id']!=$_SESSION['login']['id']): ?><a class="btn small danger-btn" data-confirm="Hapus akun ini?" href="?hapus=<?=$u['id']?>">Hapus</a><?php else: ?>Akun aktif<?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section><?php require 'partials/footer.php';?>
